module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        dout_parallel <= 0;
        dout_valid <= 0;
    end else begin
        if (din_valid) begin
            dout_parallel[dout_parallel[3:0]] <= din_serial;
            dout_parallel[3:0] <= dout_parallel[3:0] + 1;

            if (dout_parallel[3:0] == 7) begin
                dout_valid <= 1;
                dout_parallel[3:0] <= 0;
            end else begin
                dout_valid <= 0;
            end
        end
    end
end
endmodule
